mkdir -p /tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad; cd /home/user/fortress-positions; cat > /tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/cites.py <<'EOF'
import os, re, sys, collections
root = '/home/user/fortress-positions'
files = []
for dp, dn, fn in os.walk(os.path.join(root, 'explorations')):
    for f in fn:
        files.append(os.path.join(dp, f))
files.append(os.path.join(root, 'CLAUDE.md'))
skip = {'explorations/coordinator/POSITIONS.md', 'explorations/coordinator/POSITIONS-history.md'}
out = []
for p in sorted(files):
    rel = os.path.relpath(p, root)
    if rel in skip: continue
    try:
        t = open(p, encoding='utf-8').read()
    except Exception:
        continue
    for m in re.finditer(r'POSITIONS', t):
        s = t[max(0, m.start()-160): m.end()+200].replace('\n', ' ')
        out.append((rel, m.start(), s))
print(len(out))
with open(sys.argv[1], 'w') as f:
    for rel, pos, s in out:
        f.write(f'{rel}@{pos}\t{s}\n')
EOF
